const inputData = $('Execute Workflow Trigger').first().json;
const cb = inputData.callback_data || '';
let cart = [];
try { cart = JSON.parse(inputData.carrito_json || '[]'); } catch(e) {}
let contexto = {};
try { contexto = JSON.parse(inputData.contexto_json || '{}'); } catch(e) {}

if (cart.length === 0) {
  return [{
    json: {
      mensaje: '🛒 Tu carrito está vacío.',
      reply_markup: { inline_keyboard: [[{ text: '🛒 Ver Menú', callback_data: 'cat_ver_todas' }]] },
      session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: '[]', contexto_json: '{}' }
    }
  }];
}

let cartText = '🛒 *Tu Carrito*\n\n';
let subtotal = 0;
cart.forEach((item, i) => {
  const lineTotal = item.qty * item.precio;
  subtotal += lineTotal;
  cartText += (i + 1) + '. ' + item.nombre + ' x' + item.qty + ' — $' + lineTotal.toFixed(2) + '\n';
});
cartText += '\n💰 Subtotal: $' + subtotal.toFixed(2);

if (cb === 'confirm_yes') {
  cartText += '\n\n🛵 ¿Cómo deseas recibir tu pedido?';
  return [{
    json: {
      mensaje: cartText,
      reply_markup: { inline_keyboard: [
        [{ text: '🛵 Envío a Domicilio (+$2.00)', callback_data: 'deliv_yes' }],
        [{ text: '🏬 Recoger en Local ($0.00)', callback_data: 'deliv_no' }],
        [{ text: '❌ Cancelar', callback_data: 'main_menu' }]
      ]},
      session_updates: { estado_fsm: 'CARRITO', carrito_json: JSON.stringify(cart), contexto_json: JSON.stringify(contexto) }
    }
  }];
} else if (cb === 'deliv_yes' || cb === 'deliv_no') {
  contexto.tipo_entrega = (cb === 'deliv_yes') ? 'Delivery' : 'Pickup';
  let totalDesc = (cb === 'deliv_yes') ? '\n📦 Envío: $2.00' : '';

  cartText += totalDesc + '\n\n💳 Selecciona tu método de pago:';
  return [{
    json: {
      mensaje: cartText,
      reply_markup: { inline_keyboard: [
        [{ text: '💵 Efectivo (Al entregar)', callback_data: 'pay_cash' }],
        [{ text: '💳 Tarjeta (Datáfono)', callback_data: 'pay_card' }],
        [{ text: '📱 Transferencia / App', callback_data: 'pay_trans' }],
        [{ text: '⬅️ Volver', callback_data: 'confirm_yes' }]
      ]},
      session_updates: { estado_fsm: 'CARRITO', carrito_json: JSON.stringify(cart), contexto_json: JSON.stringify(contexto) }
    }
  }];
} else if (cb.startsWith('pay_')) {
  if (cb === 'pay_cash') contexto.metodo_pago = 'Efectivo';
  if (cb === 'pay_card') contexto.metodo_pago = 'Tarjeta';
  if (cb === 'pay_trans') contexto.metodo_pago = 'Transferencia';

  const envio = contexto.tipo_entrega === 'Delivery' ? 2.00 : 0.00;
  const iva = (subtotal + envio) * 0.12;
  const total = subtotal + envio + iva;

  cartText += '\n📦 Envío: $' + envio.toFixed(2);
  cartText += '\n📊 IVA (12%): $' + iva.toFixed(2);
  cartText += '\n💵 *Total a pagar: $' + total.toFixed(2) + '*';
  cartText += '\n\n📍 Entrega: ' + contexto.tipo_entrega;
  cartText += '\n💳 Pago: ' + contexto.metodo_pago;

  if (contexto.metodo_pago === 'Transferencia') {
    cartText += '\n\n⚠️ *Atención:* Para transferencias, deberás enviar tu comprobante al administrador al terminar.';
  }

  cartText += '\n\n¿Deseas realizar este pedido?';
  return [{
    json: {
      mensaje: cartText,
      reply_markup: { inline_keyboard: [
        [{ text: '✅ Sí, enviar pedido', callback_data: 'final_confirm' }],
        [{ text: '⬅️ Cambiar Pago', callback_data: (contexto.tipo_entrega === 'Delivery' ? 'deliv_yes' : 'deliv_no') }],
        [{ text: '❌ Cancelar', callback_data: 'main_menu' }]
      ]},
      session_updates: { estado_fsm: 'CARRITO', carrito_json: JSON.stringify(cart), contexto_json: JSON.stringify(contexto) }
    }
  }];
}

let recommended = null;
try {
  const menuItems = $('Read Menu').all().map(i => i.json);
  const allOrders = $('Read PEDIDOS').all().map(i => i.json.detalles_pedido || '');

  let bestMatch = null;
  let maxCount = 0;

  menuItems.forEach(menuItem => {
    if (parseInt(menuItem.stock) <= 0 || menuItem.activo !== 'TRUE') return;
    if (cart.find(c => c.id === menuItem.id_producto)) return;

    let count = 0;
    allOrders.forEach(orderStr => {
      let hasCartItem = cart.some(c => orderStr.includes(c.nombre));
      if (hasCartItem && orderStr.includes(menuItem.nombre)) {
        count++;
      }
    });

    if (count > maxCount) {
      maxCount = count;
      bestMatch = menuItem;
    }
  });

  if (!bestMatch) {
    const cartCategories = cart.map(item => {
      const m = menuItems.find(x => x.id_producto === item.id);
      return m ? m.categoria : '';
    });
    let cand = menuItems.find(m => !cartCategories.includes(m.categoria) && parseInt(m.stock) > 0 && m.activo === 'TRUE');
    if (cand) bestMatch = cand;
  }
  if (bestMatch) recommended = bestMatch;
} catch(e) { }

if (recommended) {
  cartText += '\n\n💡 *Sugerencia Inteligente:*\nLos clientes que llevan tus productos también compran **' + recommended.nombre + '** por solo $' + parseFloat(recommended.precio).toFixed(2) + '.';
  return [{
    json: {
      mensaje: cartText,
      reply_markup: { inline_keyboard: [
        [{ text: '➕ Agregar ' + recommended.nombre, callback_data: 'add_' + recommended.id_producto }],
        [{ text: '💳 Ir a Pagar', callback_data: 'confirm_yes' }],
        [{ text: '➕ Ver más menú', callback_data: 'cat_ver_todas' }]
      ]},
      session_updates: { estado_fsm: 'CARRITO', carrito_json: JSON.stringify(cart), contexto_json: JSON.stringify(contexto) }
    }
  }];
} else {
  return [{
    json: {
      mensaje: cartText,
      reply_markup: { inline_keyboard: [
        [{ text: '💳 Ir a Pagar', callback_data: 'confirm_yes' }],
        [{ text: '➕ Agregar más', callback_data: 'cat_ver_todas' }]
      ]},
      session_updates: { estado_fsm: 'CARRITO', carrito_json: JSON.stringify(cart), contexto_json: JSON.stringify(contexto) }
    }
  }];
}
